import React, { useState } from 'react';
import styles from './styles/style';
import { View, Text, Image, SafeAreaView, TouchableOpacity, Alert, ScrollView, StyleSheet } from 'react-native';
import ItemAdd from './ItemAdd.tsx';

interface ItemListProps {
  username: string;
  avatar: string;
  onLogout: () => void;
}

const ItemList: React.FC<ItemListProps> = ({ username, avatar, onLogout }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [showAddItem, setShowAddItem] = useState(false);  const [activeMenu2, setActiveMenu2] = useState<number>(1);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleUserMenu = () => {
    setIsUserMenuOpen(!isUserMenuOpen);
  };

  const handleLogout = () => {
    Alert.alert(
      'Wylogowanie',
      'Czy na pewno chcesz się wylogować?',
      [
        { text: 'Anuluj', style: 'cancel' },
        { text: 'Wyloguj', onPress: onLogout },
      ],
      { cancelable: true }
    );
  };

  const navigateToAddItem = () => {
    setShowAddItem(true);
    setIsMenuOpen(false);
  };

  const navigateToList = () => {
    setShowAddItem(false);
  };

  if (showAddItem) {
    return (
      <ItemAdd 
        username={username} 
        avatar={avatar} 
        onLogout={onLogout} 
        onNavigateToList={navigateToList} 
      />
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.menu}>
        <TouchableOpacity onPress={toggleMenu}>
          <Image
            source={require('./assets/menu.png')}
            style={styles.menuIcon}
          />
        </TouchableOpacity>
        <Image
          source={require('./assets/skinradar.png')}
          style={styles.logo}
        />
        <TouchableOpacity onPress={toggleUserMenu}>
          <Image
            source={{ uri: avatar }}
            style={styles.avatar}
          />
        </TouchableOpacity>
      </View>
      
      <ScrollView contentContainerStyle={styles.scrollContainer} showsVerticalScrollIndicator={false}>
        {isMenuOpen && (
          <View style={styles.dropdownMenu}>
            <TouchableOpacity style={styles.dropdownButton}>
              <Text style={styles.dropdownButtonText}>LISTA</Text>
            </TouchableOpacity>
            <TouchableOpacity style={styles.dropdownButton} onPress={navigateToAddItem}>
              <Text style={styles.dropdownButtonText}>DODAJ</Text>
            </TouchableOpacity>
          </View>
        )}

        {isUserMenuOpen && (
          <View style={styles.userMenu}>
            <Text style={styles.userMenuText}>{username}</Text>
            <TouchableOpacity style={styles.logoutButton} onPress={handleLogout}>
              <Image
                source={require('./assets/logout.png')}
                style={styles.logoutIcon}
              />
            </TouchableOpacity>
          </View>
        )}

        <View style={localStyles.content}>
          <Text style={styles.title}>Witaj w aplikacji SkinRadar!</Text>
        </View>
      </ScrollView>

      <View style={styles.menu2}>{[
          require('./assets/settings.png'),
          require('./assets/bell.png'),
          require('./assets/questmark.png'),
        ].map((icon, idx) => (
          <TouchableOpacity
            key={idx}
            onPress={() => {
              setActiveMenu2(idx);
            }}
            style={styles.menu2Button}
            activeOpacity={0.7}
          >
            <View style={[
              styles.menu2IconWrapper,
              activeMenu2 === idx && styles.menu2IconWrapperActive
            ]}>
              <Image
                source={icon}
                style={[
                  styles.menuButtonIcon,
                  activeMenu2 === idx && styles.menuButtonIconActive,
                ]}
              />
            </View>
          </TouchableOpacity>
        ))}
      </View>
    </SafeAreaView>
  );
};

const localStyles = StyleSheet.create({
  content: {
    flex: 1,
    padding: 20,
    justifyContent: 'center',
    alignItems: 'center',
  }
});

export default ItemList;
